  <script>
    // JS Logic for Interactions

    // 1. Generate 94 mock rows to reach 100 total
    const tbody = document.getElementById('cryptoTableBody');
    const prefixes = ['Pro', 'Eco', 'Nova', 'Ultra', 'Hyper', 'Giga', 'Omni', 'Max', 'Aero', 'Zen'];
    const suffixes = ['Coin', 'Token', 'Chain', 'Network', 'Ledger', 'Fi', 'Node'];

    let html = '';
    let startRank = 8; // skipping 6 since SOL is 7 in brief
    for (let i = 0; i < 94; i++) {
      const rank = startRank + i;
      const name = prefixes[Math.floor(Math.random() * prefixes.length)] + suffixes[Math.floor(Math.random() * suffixes.length)];
      const symbol = name.substring(0, 3).toUpperCase() + (Math.random()>0.5?'X':'');
      const price = (Math.random() * 100).toFixed(2);
      const isUp = Math.random() > 0.4;
      const changeClass = isUp ? 'text-green' : 'text-red';
      const sign = isUp ? '+' : '-';
      const change1h = `${sign}${(Math.random() * 2).toFixed(2)}%`;
      const change24h = `${sign}${(Math.random() * 8).toFixed(2)}%`;
      const change7d = `${sign}${(Math.random() * 15).toFixed(2)}%`;
      const mcap = `$${(Math.random() * 50 + 1).toFixed(2)}B`;
      const vol = `$${(Math.random() * 5 + 0.1).toFixed(2)}B`;
      const supply = `${(Math.random() * 900 + 10).toFixed(2)}M ${symbol}`;
      const sparklineClass = isUp ? 'positive' : 'negative';
      const sparks = ['▂▃▄▅▆', '▅▆▄▃▂', '▃▄▅▇▆', '▅▄▃▂ ', '▂▃▅▆▇'];
      const spark = sparks[Math.floor(Math.random()*sparks.length)];

      html += `
        <tr>
          <td class="col-rank">${rank}</td>
          <td class="col-name"><div style="width:20px;height:20px;border-radius:10px;background:#E2E6EE"></div> ${name} <span class="col-symbol">${symbol}</span></td>
          <td>$${price}</td>
          <td class="${changeClass}">${change1h}</td>
          <td class="${changeClass}">${change24h}</td>
          <td class="${changeClass}">${change7d}</td>
          <td>${mcap}</td>
          <td>${vol}</td>
          <td>${supply}</td>
          <td class="sparkline ${sparklineClass}">${spark}</td>
        </tr>
      `;
    }
    tbody.insertAdjacentHTML('beforeend', html);

    // 2. Tabs logic
    const categoryTabs = document.querySelectorAll('#categoryTabs .tab');
    categoryTabs.forEach(tab => {
      tab.addEventListener('click', (e) => {
        if(e.target.innerText.includes('More')) return;
        categoryTabs.forEach(t => t.classList.remove('active'));
        e.target.classList.add('active');
        simulateLoading();
      });
    });

    const networkTabs = document.querySelectorAll('#networkTabs .net-tab');
    networkTabs.forEach(tab => {
      tab.addEventListener('click', (e) => {
        networkTabs.forEach(t => t.classList.remove('active'));
        e.target.classList.add('active');
        simulateLoading();
      });
    });

    // 3. Toggles (Columns & Filters)
    const btnFilters = document.getElementById('btnFilters');
    const dropdownFilters = document.getElementById('dropdownFilters');
    btnFilters.addEventListener('click', (e) => {
      e.stopPropagation();
      dropdownFilters.style.display = dropdownFilters.style.display === 'block' ? 'none' : 'block';
      dropdownColumns.style.display = 'none';
    });

    const btnColumns = document.getElementById('btnColumns');
    const dropdownColumns = document.getElementById('dropdownColumns');
    btnColumns.addEventListener('click', (e) => {
      e.stopPropagation();
      dropdownColumns.style.display = dropdownColumns.style.display === 'block' ? 'none' : 'block';
      dropdownFilters.style.display = 'none';
    });

    document.addEventListener('click', () => {
      dropdownFilters.style.display = 'none';
      dropdownColumns.style.display = 'none';
    });

    dropdownFilters.addEventListener('click', e => e.stopPropagation());
    dropdownColumns.addEventListener('click', e => e.stopPropagation());

    // 4. Promo Banner Carousel
    const promos = [
      "CTP Launch: Secure $GENIUS Airdrop — Join Now ➔",
      "New Listing: Solana Futures Trading Live on DexScan ➔",
      "Market Update: Bitcoin breaks $75K resistance level ➔"
    ];
    let promoIdx = 0;
    const promoEl = document.getElementById('promoCarousel');
    promoEl.addEventListener('click', () => {
      promoIdx = (promoIdx + 1) % promos.length;
      promoEl.innerText = promos[promoIdx];
    });
    setInterval(() => {
      promoIdx = (promoIdx + 1) % promos.length;
      promoEl.innerText = promos[promoIdx];
    }, 5000);

    // 5. Pagination
    const pageBtns = document.querySelectorAll('.page-btn');
    pageBtns.forEach(btn => {
      btn.addEventListener('click', (e) => {
        pageBtns.forEach(b => b.classList.remove('active'));
        e.target.classList.add('active');
        simulateLoading();
        window.scrollTo({top: document.querySelector('h1').offsetTop - 20, behavior: 'smooth'});
      });
    });

    // 6. Accordion Market Summary
    const readMoreBtn = document.getElementById('readMoreBtn');
    const summaryMore = document.getElementById('summaryMore');
    readMoreBtn.addEventListener('click', () => {
      if (summaryMore.classList.contains('open')) {
        summaryMore.classList.remove('open');
        readMoreBtn.innerText = 'Read More';
      } else {
        summaryMore.classList.add('open');
        readMoreBtn.innerText = 'Show Less';
      }
    });

    function simulateLoading() {
      tbody.style.opacity = '0.5';
      setTimeout(() => {
        tbody.style.opacity = '1';
      }, 300);
    }
  </script>
